import {getDb} from '../db';
import {tvSelection,tvHistory} from '../db/schema';
import {eq,desc} from 'drizzle-orm';
export async function selected(){return (await getDb().select().from(tvSelection).where(eq(tvSelection.id,'main')).limit(1))[0]||null;}
export async function history(){return getDb().select().from(tvHistory).orderBy(desc(tvHistory.usedAt)).limit(10);}
export async function saveSelection(code:string,title:string){const now=Date.now();const item={id:'main',code,title,updatedAt:now};await getDb().batch([getDb().insert(tvSelection).values(item).onConflictDoUpdate({target:tvSelection.id,set:{code,title,updatedAt:now}}),getDb().insert(tvHistory).values({code,title,usedAt:now}).onConflictDoUpdate({target:tvHistory.code,set:{title,usedAt:now}})]);return selected();}
export async function saveBackup(backupCode:string|null){if(!await selected())throw new Error('اختر البث الرئيسي أولًا.');await getDb().update(tvSelection).set({backupCode}).where(eq(tvSelection.id,'main'));return selected();}

