export async function upstream(url:string|URL,init:RequestInit={},attempts=2):Promise<Response>{
 for(let i=0;i<attempts;i++){try{const r=await fetch(url,{...init,redirect:'manual',signal:AbortSignal.timeout(12000)});if(i+1<attempts&&[502,503,504].includes(r.status)){await r.body?.cancel();continue;}return r;}catch(e){if(i+1===attempts)throw new Error('تعذر الاتصال بمزوّد البث. حاول مجددًا بعد قليل.');}}
 throw new Error('تعذر الاتصال بالمصدر.');
}

